input.command:
cd /tmp
cat > /tmp/cdp_test.ts <<'EOF'
// Drive system Chrome over CDP using ONLY Bun built-ins (fetch + WebSocket). No deps.
const proc = Bun.spawn([
  "google-chrome-stable","--headless=new","--no-sandbox","--disable-gpu",
  "--remote-debugging-port=9223","--remote-allow-origins=*","about:blank"
], { stderr: "pipe" });
// wait for devtools
let wsUrl = "";
for (let i=0;i<40;i++){
  try { const r = await fetch("http://127.0.0.1:9223/json/version"); const j = await r.json(); wsUrl = j.webSocketDebuggerUrl; break; } catch {}
  await Bun.sleep(100);
}
if(!wsUrl){ console.log("NO WS"); proc.kill(); process.exit(1);}
const ws = new WebSocket(wsUrl);
const logs: string[] = [];
let id=0; const pending = new Map<number,(v:any)=>void>();
function send(method:string, params:any={}, sessionId?:string){ return new Promise(res=>{ const mid=++id; pending.set(mid,res); ws.send(JSON.stringify({id:mid,method,params,sessionId})); }); }
await new Promise(r=> ws.addEventListener("open", r));
ws.addEventListener("message",(e)=>{ const m=JSON.parse(e.data as string);
  if(m.id && pending.has(m.id)){ pending.get(m.id)!(m.result); pending.delete(m.id); }
  if(m.method==="Runtime.consoleAPICalled"){ logs.push("console."+m.params.type+": "+ (m.params.args?.map((a:any)=>a.value).join(" ")) ); }
  if(m.method==="Runtime.exceptionThrown"){ logs.push("EXCEPTION: "+ m.params.exceptionDetails?.exception?.description); }
});
// attach to a target/page
const {targetId} = await send("Target.createTarget",{url:"about:blank"}) as any;
const {sessionId} = await send("Target.attachToTarget",{targetId,flatten:true}) as any;
await send("Runtime.enable",{},sessionId);
await send("Page.enable",{},sessionId);
const html = await Bun.file("/tmp/test.html").text();
await send("Page.navigate",{url:"data:text/html;base64,"+btoa(html)},sessionId);
await Bun.sleep(500);
// scan computed animation on .x
const r = await send("Runtime.evaluate",{expression:`(()=>{const e=document.querySelector('.x');const cs=getComputedStyle(e);return JSON.stringify({anim:cs.animationName,dur:cs.animationDuration,trans:cs.transitionProperty});})()`,returnByValue:true},sessionId) as any;
console.log("LOGS:", JSON.stringify(logs));
console.log("COMPUTED:", r?.result?.value);
ws.close(); proc.kill();
EOF
timeout 40 bun run /tmp/cdp_test.ts 2>&1 | head -20

cd /tmp
# Pure static lint test on the html (no browser) - prove regex scans work in bun
cat > /tmp/lint_test.ts <<'EOF'
const html = await Bun.file("/tmp/test.html").text();
const hexColors = [...html.matchAll(/#[0-9a-fA-F]{3,8}\b/g)].map(m=>m[0]);
const fontSizes = [...html.matchAll(/font-size\s*:\s*[^;}]+/g)].map(m=>m[0]);
const hasReducedMotion = /@media[^{]*prefers-reduced-motion/.test(html);
const usesVars = /var\(--/.test(html) || /:root\s*\{[^}]*--/.test(html);
const keyframes = [...html.matchAll(/@keyframes\s+[\w-]+/g)].length;
const cdnAnim = /(gsap|animejs|anime\.min|aos\.js|lottie|framer-motion|scrollreveal)/i.test(html);
console.log(JSON.stringify({hexColors:hexColors.length, uniqHex:[...new Set(hexColors)].length, fontSizes:fontSizes.length, hasReducedMotion, usesVars, keyframes, cdnAnim},null,2));
EOF
bun run /tmp/lint_test.ts
echo "=== axe-core feasibility: is it a single npm pkg injectable as a string? ==="
timeout 15 curl -sI https://cdn.jsdelivr.net/npm/axe-core/axe.min.js 2>&1 | head -1

